import { useState, useEffect, useContext } from "react";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";
import { useNavigate } from "react-router-dom";

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState(null);

  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      alert(err.response?.data?.error || err.message);
    }
  };

  // ---------------- Backend API calls ----------------
  const fetchVotingState = async () => {
    try {
      const res = await api.get("/admin/voting-state");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const approveUser = async (id) => {
    try {
      await api.post(`/admin/approve-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const rejectUser = async (id) => {
    try {
      await api.post(`/admin/reject-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const generateReport = async () => {
    try {
      const res = await api.post("/admin/generate-report");
      setReportHash(res.data.hash);
    } catch (err) {
      handleApiError(err);
    }
  };

  const deleteCandidate = async (id) => {
    if (!window.confirm("Delete this candidate?")) return;
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchCandidates();
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchResults = async () => {
    try {
      const res = await api.get("/admin/results");
      setResults(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  // ---------------- Initial load ----------------
  useEffect(() => {
    if (!token) {
      navigate("/login");
      return;
    }

    const init = async () => {
      await fetchVotingState();
      await fetchPendingUsers();
      await fetchCandidates();
      await fetchLogs();
    };
    init();
  }, [token]);

  // ---------------- Auto-refresh results every 5 seconds ----------------
  useEffect(() => {
    fetchResults(); // initial fetch
    const interval = setInterval(fetchResults, 5000);
    return () => clearInterval(interval);
  }, []);

  // ---------------- JSX ----------------
  return (
    <div className="min-h-screen bg-gray-100">
      {/* Header */}
      <header className="bg-white shadow-md py-4 px-6 flex justify-between items-center">
        <h1 className="text-2xl font-bold">iVote Admin Dashboard</h1>
        <button
          onClick={() => { logout(); navigate("/login"); }}
          className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700"
        >
          Logout
        </button>
      </header>

      <main className="p-6 space-y-6">
        {/* Voting Status */}
        <section className="bg-white p-6 rounded-xl shadow-md flex justify-between items-center">
          <div>
            <h2 className="text-xl font-semibold">Voting Status</h2>
            <p className={votingOpen ? "text-green-600" : "text-red-600"}>
              {votingOpen ? "Open" : "Closed"}
            </p>
          </div>
          <button
            onClick={toggleVoting}
            className={`px-6 py-3 rounded-lg font-semibold text-white ${votingOpen ? "bg-red-600 hover:bg-red-700" : "bg-green-600 hover:bg-green-700"}`}
          >
            {votingOpen ? "Close Voting" : "Open Voting"}
          </button>
        </section>

        {/* Pending Users */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <h2 className="text-xl font-semibold mb-4">Pending Voter Registrations</h2>
          {pendingUsers.length === 0 ? (
            <p className="text-gray-500">No pending users.</p>
          ) : (
            <table className="w-full table-auto border-collapse border border-gray-200">
              <thead>
                <tr className="bg-gray-100">
                  <th className="border px-4 py-2">Student Number</th>
                  <th className="border px-4 py-2">Name</th>
                  <th className="border px-4 py-2">Email</th>
                  <th className="border px-4 py-2">Actions</th>
                </tr>
              </thead>
              <tbody>
                {pendingUsers.map((user) => (
                  <tr key={user.id}>
                    <td className="border px-4 py-2">{user.studentNumber}</td>
                    <td className="border px-4 py-2">{user.name}</td>
                    <td className="border px-4 py-2">{user.email}</td>
                    <td className="border px-4 py-2 space-x-2">
                      <button onClick={() => approveUser(user.id)} className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700">Approve</button>
                      <button onClick={() => rejectUser(user.id)} className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700">Reject</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </section>

        {/* Candidates */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <h2 className="text-xl font-semibold mb-4">Candidates</h2>
          <table className="w-full table-auto border-collapse border border-gray-200">
            <thead>
              <tr className="bg-gray-100">
                <th className="border px-4 py-2">Name</th>
                <th className="border px-4 py-2">Position</th>
                <th className="border px-4 py-2">Party</th>
                <th className="border px-4 py-2">Actions</th>
              </tr>
            </thead>
            <tbody>
              {candidates.map((c) => (
                <tr key={c.id} className="hover:bg-gray-50">
                  <td className="border px-4 py-2">{c.name}</td>
                  <td className="border px-4 py-2">{c.position}</td>
                  <td className="border px-4 py-2">{c.party || "-"}</td>
                  <td className="border px-4 py-2 space-x-2">
                    <button onClick={() => deleteCandidate(c.id)} className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700">Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>

        {/* System Logs */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <h2 className="text-xl font-semibold mb-4">System Logs</h2>
          {logs.length === 0 ? (
            <p className="text-gray-500">No logs available.</p>
          ) : (
            <ul className="space-y-2 max-h-64 overflow-y-auto">
              {logs.map((log) => (
                <li key={log.id} className="text-gray-700">
                  {log.action} <span className="text-gray-400 text-sm">{new Date(log.createdAt).toLocaleString()}</span>
                </li>
              ))}
            </ul>
          )}
        </section>

        {/* Reports */}
        <section className="bg-white p-6 rounded-xl shadow-md flex flex-col items-start space-y-3">
          <h2 className="text-xl font-semibold text-gray-800">Reports</h2>
          <button onClick={generateReport} className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700">Generate Final Report</button>
          {reportHash && <p className="text-gray-600 mt-2">Cryptographic Hash: <span className="font-mono">{reportHash}</span></p>}
        </section>

       {/* Election Results */}
<section className="bg-white p-6 rounded-xl shadow-md flex flex-col items-start space-y-3">
  <div className="flex justify-between w-full items-center">
    <h2 className="text-xl font-semibold text-gray-800">Election Results</h2>
    <button
      onClick={fetchResults}
      className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
    >
      Refresh Results
    </button>
  </div>

  {results && Object.keys(results.positionResults).map((position) => (
    <div key={position} className="mt-4 w-full">
      <h3 className="text-lg font-semibold">{position}</h3>
      <table className="w-full table-auto border-collapse border border-gray-200">
        <thead>
          <tr className="bg-gray-100">
            <th className="border px-4 py-2">Candidate</th>
            <th className="border px-4 py-2">Party</th>
            <th className="border px-4 py-2">Votes</th>
          </tr>
        </thead>
        <tbody>
          {results.positionResults[position].map((c) => (
            <tr key={c.id} className="hover:bg-gray-50">
              <td className="border px-4 py-2">{c.name}</td>
              <td className="border px-4 py-2">{c.party || "-"}</td>
              <td className="border px-4 py-2">{c.votes}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <p className="mt-1 text-green-600 font-semibold">
        Winner: {results.winners[position]?.name || "N/A"}
      </p>
    </div>
  ))}
</section>

      </main>
    </div>
  );
}
